-- Migração dos produtos existentes do index.html para a tabela produtos
-- Gerado automaticamente. Rodar DEPOIS de criar o schema (schema.sql).

ON CONFLICT (id) DO NOTHING;

-- Ajusta a sequência de id pra continuar depois do maior id migrado,
-- assim produtos novos cadastrados pelo painel não colidem com os antigos.
SELECT setval('produtos_id_seq', (SELECT MAX(id) FROM produtos));
